import itertools
verts = [(x,y,z) for x in (0,1) for y in (0,1) for z in (0,1)]
idx = {v:i for i,v in enumerate(verts)}
edges = []
for v in verts:
    for k in range(3):
        w = list(v); w[k] ^= 1; w = tuple(w)
        if idx[v] < idx[w]:
            edges.append((idx[v], idx[w]))
faces = []
for k in range(3):
    for c in (0,1):
        fv = [i for i,v in enumerate(verts) if v[k]==c]
        faces.append([e for e in edges if e[0] in fv and e[1] in fv])
for r in range(5,13):
    found=None
    for combo in itertools.combinations(range(12), r):
        s=set(combo)
        if all(sum(1 for e in f if e in s)>=2 for f in faces):
            found=combo; break
    if found:
        print("min =", r)
        print("black edges:", [edges[i] for i in found])
        s=set(found)
        print("per-face black counts:", [sum(1 for e in f if e in s) for f in faces])
        break
"}

