def is_prime(n):
    if n < 2: return False
    i = 2
    while i*i <= n:
        if n % i == 0: return False
        i += 1
    return True

def is_squarefree(n):
    # n >= 1
    if n == 0:
        return False
    i = 2
    while i*i <= n:
        if n % (i*i) == 0:
            return False
        i += 1
    return True

def primes_below(n):
    return [x for x in range(2, n) if is_prime(x)]

def good(p):
    for q in primes_below(p):
        r = p % q
        if not is_squarefree(r):
            return False, (q, r)
    return True, None

results = []
for p in range(2, 2000):
    if is_prime(p):
        ok, witness = good(p)
        results.append((p, ok, witness))

good_list = [p for p, ok, w in results if ok]
print("Good primes up to 2000:", good_list)
# show first few failures with witnesses
for p, ok, w in results:
    if not ok and p < 60:
        print(p, "fails at q,r =", w)
